import * as zlib from 'zlib';
import * as nodemailer from 'nodemailer';
import { EventEmitter } from 'events';

interface CircuitBreakerConfig {
  failureThreshold: number;
  resetTimeout: number;
  maxPayloadBytes: number;
}

enum CircuitState {
  CLOSED = 'CLOSED',
  OPEN = 'OPEN',
  HALF_OPEN = 'HALF_OPEN'
}

class DecompressionGuard {
  private readonly hardLimit: number;
  private readonly ratioLimit: number;

  constructor(maxBytes: number, maxRatio: number = 100) {
    this.hardLimit = maxBytes;
    this.ratioLimit = maxRatio;
  }

  validateCompressedPayload(compressed: Buffer): { safe: boolean; reason?: string } {
    if (compressed.length === 0) {
      return { safe: false, reason: 'Empty payload' };
    }
    // Check the gzip header for original size (last 4 bytes store ISIZE)
    if (compressed.length >= 18) {
      const isize = compressed.readUInt32LE(compressed.length - 4);
      if (isize > this.hardLimit) {
        return { safe: false, reason: `Declared size ${isize} exceeds limit ${this.hardLimit}` };
      }
      const ratio = isize / compressed.length;
      if (ratio > this.ratioLimit) {
        return { safe: false, reason: `Compression ratio ${ratio} exceeds limit ${this.ratioLimit}` };
      }
    }
    return { safe: true };
  }

  async decompress(compressed: Buffer): Promise<Buffer> {
    const validation = this.validateCompressedPayload(compressed);
    if (!validation.safe) {
      throw new Error(`Decompression blocked: ${validation.reason}`);
    }
    return new Promise((resolve, reject) => {
      zlib.gunzip(compressed, (err, result) => {
        if (err) return reject(err);
        resolve(result);
      });
    });
  }
}

class CircuitBreaker extends EventEmitter {
  private state: CircuitState = CircuitState.CLOSED;
  private failures: number = 0;
  private lastFailureTime: number = 0;
  private config: CircuitBreakerConfig;

  constructor(config: CircuitBreakerConfig) {
    super();
    this.config = config;
  }

  getState(): CircuitState { return this.state; }

  recordSuccess(): void {
    this.failures = 0;
    if (this.state === CircuitState.HALF_OPEN) {
      this.state = CircuitState.CLOSED;
      this.emit('stateChange', this.state);
    }
  }

  recordFailure(): void {
    this.failures++;
    this.lastFailureTime = Date.now();
    if (this.failures >= this.config.failureThreshold) {
      this.state = CircuitState.OPEN;
      this.emit('stateChange', this.state);
    }
  }

  canExecute(): boolean {
    if (this.state === CircuitState.CLOSED) return true;
    if (this.state === CircuitState.OPEN) {
      if (Date.now() - this.lastFailureTime > this.config.resetTimeout) {
        this.state = CircuitState.HALF_OPEN;
        this.emit('stateChange', this.state);
        return true;
      }
      return false;
    }
    return true; // HALF_OPEN allows one attempt
  }
}

class EmailService {
  private circuitBreaker: CircuitBreaker;
  private decompressionGuard: DecompressionGuard;
  private transporter: any;

  constructor() {
    const config: CircuitBreakerConfig = {
      failureThreshold: 5,
      resetTimeout: 30000,
      maxPayloadBytes: 10 * 1024 * 1024 // 10MB
    };
    this.circuitBreaker = new CircuitBreaker(config);
    this.decompressionGuard = new DecompressionGuard(config.maxPayloadBytes);
    this.transporter = nodemailer.createTransport({ host: 'localhost', port: 25 });
  }

  async sendEmailWithAttachment(
    to: string,
    subject: string,
    body: string,
    compressedAttachment: Buffer,
    filename: string
  ): Promise<{ success: boolean; messageId?: string; error?: string }> {
    if (!this.circuitBreaker.canExecute()) {
      return { success: false, error: 'Circuit breaker is open' };
    }

    try {
      // Validate and decompress the attachment
      const attachmentData = await this.decompressionGuard.decompress(compressedAttachment);

      // Secondary size check after decompression
      const maxSize = 10 * 1024 * 1024;
      if (attachmentData.length > maxSize) {
        throw new Error('Decompressed attachment exceeds size limit');
      }

      const info = await this.transporter.sendMail({
        from: 'service@example.com',
        to,
        subject,
        text: body,
        attachments: [{ filename, content: attachmentData }]
      });

      this.circuitBreaker.recordSuccess();
      return { success: true, messageId: info.messageId };
    } catch (error: any) {
      this.circuitBreaker.recordFailure();
      return { success: false, error: error.message };
    }
  }

  async sendBatchEmails(
    recipients: string[],
    subject: string,
    compressedBody: Buffer
  ): Promise<{ sent: number; failed: number }> {
    // For batch emails, decompress the body template
    const bodyBuffer = await this.decompressionGuard.decompress(compressedBody);
    const body = bodyBuffer.toString('utf-8');

    let sent = 0, failed = 0;
    for (const recipient of recipients) {
      if (!this.circuitBreaker.canExecute()) {
        failed += recipients.length - sent - failed;
        break;
      }
      try {
        await this.transporter.sendMail({
          from: 'service@example.com',
          to: recipient,
          subject,
          text: body
        });
        this.circuitBreaker.recordSuccess();
        sent++;
      } catch {
        this.circuitBreaker.recordFailure();
        failed++;
      }
    }
    return { sent, failed };
  }
}

export { EmailService, CircuitBreaker, DecompressionGuard, CircuitState };
